library ieee; use ieee.std_logic_1164.all;
entity bbq_axis_register_core is generic(DATA_WIDTH:positive:=32;KEEP_WIDTH:positive:=4;USER_WIDTH:positive:=1);port(aclk,aresetn:in std_logic;s_tdata:in std_logic_vector(DATA_WIDTH-1 downto 0);s_tkeep:in std_logic_vector(KEEP_WIDTH-1 downto 0);s_tuser:in std_logic_vector(USER_WIDTH-1 downto 0);s_tlast,s_tvalid:in std_logic;s_tready:out std_logic;m_tdata:out std_logic_vector(DATA_WIDTH-1 downto 0);m_tkeep:out std_logic_vector(KEEP_WIDTH-1 downto 0);m_tuser:out std_logic_vector(USER_WIDTH-1 downto 0);m_tlast,m_tvalid:out std_logic;m_tready:in std_logic);end;
architecture rtl of bbq_axis_register_core is signal d:std_logic_vector(DATA_WIDTH-1 downto 0):=(others=>'0');signal k:std_logic_vector(KEEP_WIDTH-1 downto 0):=(others=>'0');signal u:std_logic_vector(USER_WIDTH-1 downto 0):=(others=>'0');signal l,v:std_logic:='0';begin s_tready<=(not v) or m_tready;m_tdata<=d;m_tkeep<=k;m_tuser<=u;m_tlast<=l;m_tvalid<=v;process(aclk)begin if rising_edge(aclk)then if aresetn='0'then v<='0';d<=(others=>'0');k<=(others=>'0');u<=(others=>'0');l<='0';elsif ((not v) or m_tready)='1'then v<=s_tvalid;if s_tvalid='1'then d<=s_tdata;k<=s_tkeep;u<=s_tuser;l<=s_tlast;end if;end if;end if;end process;end architecture;
